# (pattern over the string's "where", files to check, case-insensitive?)
SIG_FILE_HINTS = [
    (r"production\.log|foreman/production|\bUI\b|hammer", ["var/log/foreman/production.log"], True),
    (r"\bAPI\b", ["var/log/foreman/production.log"], False),                    # not "GSSAPI"
    (r"proxy\.log|foreman-proxy", ["var/log/foreman-proxy/proxy.log"], True),
    (r"rhsm\.log|client output|subscription-manager|rhsmcertd|virt-who", ["var/log/rhsm/rhsm.log"], True),
    (r"rhsmcertd", ["var/log/rhsm/rhsmcertd.log"], True),
    (r"candlepin", ["var/log/candlepin/candlepin.log", "var/log/candlepin/error.log"], True),
    (r"tomcat|catalina", ["var/log/tomcat/catalina.*.log", "var/log/tomcat/localhost.*.log"], True),
    (r"satellite\.log|installer", ["var/log/foreman-installer/satellite.log", "var/log/foreman-installer/capsule.log"], True),
    (r"capsule\.log", ["var/log/foreman-installer/capsule.log"], True),
    (r"foreman-maintain|satellite-maintain", ["var/log/foreman-maintain/foreman-maintain.log"], True),
    (r"audit", ["var/log/audit/audit.log"], True),
    (r"leapp", ["var/log/leapp/leapp-report.txt", "var/log/leapp/leapp-preupgrade.log", "var/log/leapp/leapp-upgrade.log"], True),
    (r"postgres|pgsql", ["var/lib/pgsql/data/log/postgresql-*.log", "var/lib/pgsql/data/pg_log/postgresql-*.log"], True),
    (r"messages|journal|pulpcore|systemd|kernel|dynflow-sidekiq|puppetserver|virt-who", ["var/log/messages"], True),
    (r"puppet", ["var/log/puppetlabs/puppetserver/puppetserver.log"], True),
    (r"insights|rhc\b|cloud connector", ["var/log/insights-client/insights-client.log"], True),
    (r"dnf|yum", ["var/log/dnf.log", "var/log/dnf.rpm.log", "var/log/yum.log"], True),
    (r"httpd|apache|error_log|ssl_error", ["var/log/httpd/error_log", "var/log/httpd/foreman-ssl_error_ssl.log"], True),
    (r"access", ["var/log/httpd/foreman-ssl_access_ssl.log"], True),
    (r"\bsecure\b", ["var/log/secure"], True),
    (r"\btasks?\b|dynflow|task export|Dynflow console", ["sos_commands/foreman/foreman_tasks_tasks", "sos_commands/foreman/dynflow_steps"], True),
]
SIG_DEFAULT_FILES = ["var/log/messages", "var/log/foreman/production.log", "var/log/rhsm/rhsm.log", "var/log/foreman-proxy/proxy.log",
                     "var/log/foreman-installer/satellite.log", "var/log/foreman-installer/capsule.log", "var/log/foreman-maintain/foreman-maintain.log",
                     "sos_commands/foreman/dynflow_steps"]
SIG_PATH_RX = re.compile(r"\b((?:var|etc|sos_commands|root)/[\w.@+*{}/-]+)")


def sig_files(t, s, cache):
    """Files a known string is checked in: the paths it names, else the usual logs. Current files only, not rotated copies."""
    key = s["w"]
    if key in cache:
        return cache[key]
    pats = [p.rstrip(".,;)") for p in SIG_PATH_RX.findall(s["w"] or "")]
    for rx, files, nocase in SIG_FILE_HINTS:
        if re.search(rx, s["w"] or "", re.I if nocase else 0):
            pats.extend(files)
    if not pats:
        pats = list(SIG_DEFAULT_FILES)
    out = []
    for p in pats:
        if "*" in p:
            out.extend(t.glob(p))
        elif t.exists(p) and os.path.isfile(os.path.join(t.root, p)):
            out.append(p)
        elif p == "var/log/messages":
            j = t.first(["sos_commands/logs/journalctl_--no-pager*"])
            if j:
                out.append(j)
    seen, res = set(), []
    for p in out:
        if p not in seen:
            seen.add(p)
            res.append(p)
    cache[key] = res
    return res


def sig_applies(s, role):
    return s["use"] and (s.get("role", "any") == "any" or role in ("satellite", "capsule"))


TASK_TABLE_RX = re.compile(r"(?:^|/)(?:foreman_tasks_tasks|dynflow_\w+)$")
SUCCESS_ROW = re.compile(rb"(?:^|[,|])\s*success\s*(?:[,|]|$)")


def _containers(frags):
    """For each fragment, the shortest other fragments that contain it: 'Unable to detect features' sits inside
    'Unable to detect features ([RestClient::SSLCertificateNotVerified]', so a line with the longer one counts once."""
    out = {}
    fl = sorted(set(frags), key=len)
    for i, a in enumerate(fl):
        cont = [b for b in fl[i + 1:] if a in b and len(b) > len(a)]
        minimal = [b for b in cont if not any(c != b and c in b for c in cont)]
        if minimal:
            out[a] = minimal
    return out


KS_PIECE = 16 * 1024 * 1024


_LINE_RX = {}


def _line_rx(pat):
    if pat not in _LINE_RX:
        _LINE_RX[pat] = re.compile(pat.encode("utf-8"))
    return _LINE_RX[pat]


def _sig_key(s):
    return (s["f"].encode("utf-8", "replace"), s["rx"]) if s.get("rx") else s["f"].encode("utf-8", "replace")


_MON3 = frozenset(m.encode() for m in ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"))
_TIME_CACHE = {}
_ROW_DATE = re.compile(rb"(\d{4})-(\d\d)-(\d\d)[ T](\d\d):(\d\d)")


def _line_time(data, ls, ref, table, off, back=40):
    """The time of the line starting at ls: its own leading time, else that of the nearest line above it that has one
    (a backtrace or a wrapped table row belongs to the entry above). In a task table it is the row's first date, its
    started_at, which the database writes in UTC: shifted by the host's offset to read like the logs."""
    pos = ls
    for _ in range(back):
        le = data.find(b"\n", pos)
        le = len(data) if le < 0 else le
        if table:
            m = _ROW_DATE.search(data, pos, min(le, pos + 4000))
            if m:
                try:
                    return datetime.datetime(*[int(x) for x in m.groups()]) + datetime.timedelta(minutes=off)
                except ValueError:
                    return None
        else:
            head = data[pos:min(le, pos + 100)]
            # a leading ISO or syslog time: lines that share their first 16 bytes share the minute, so it is read once
            key = head[:16] if (head[:4].isdigit() or head[:3] in _MON3) else None
            if key is not None and key in _TIME_CACHE:
                w = _TIME_CACHE[key]
            else:
                w = parse_when(head.decode("utf-8", "replace"), ref)
                if key is not None:
                    if len(_TIME_CACHE) > 200000:
                        _TIME_CACHE.clear()
                    _TIME_CACHE[key] = w
            if w:
                return w
        if pos == 0:
            return None
        pos = data.rfind(b"\n", 0, pos - 1) + 1
    return None


class _When(object):
    """When one string was seen in one file: first and last time, lines per day, lines in the part of a year-less log
    that is over 12 months old (no year to place them by), and lines with no time anywhere near them."""
    __slots__ = ("first", "last", "days", "old", "notime")

    def __init__(self):
        self.first = self.last = None
        self.days, self.old, self.notime = {}, 0, 0

    def add(self, w, old):
        if old:
            self.old += 1
        elif w is None:
            self.notime += 1
        else:
            if self.first is None or w < self.first:
                self.first = w
            if self.last is None or w > self.last:
                self.last = w
            d = w.date()
            self.days[d] = self.days.get(d, 0) + 1


def _count_file(job):
    """Count byte fragments in one whole file, read in pieces cut at line ends (no fragment spans a line), and note
    when each counted line was written. Returns (rel, {fragment: [count, line of the first match or None]}, late,
    {fragment: _When}); counts None for binary or unreadable files."""
    root, rel, frags, table, deadline = job[:5]
    ref, off = (job[5], job[6]) if len(job) > 6 else (None, 0)
    import time
    counts = dict((f, [0, None]) for f in frags)
    whens = dict((f, _When()) for f in frags)
    plain = [f for f in frags if not isinstance(f, tuple)]
    conts = _containers(plain)                 # an occurrence inside a longer known string is that string's, not this one's
    full = os.path.join(root, rel)
    ycut = 0 if table or ref is None else file_year_cut(full, ref)
    _TIME_CACHE.clear()                        # a year-less time depends on the reference: never carried from one report to another
    lines_before, bytes_before, rest, first = 0, 0, b"", True
    try:
        fh = open(full, "rb")
    except OSError:
        return rel, None, False, {}
    with fh:
        while True:
            if time.time() > deadline:
                return rel, None, True, {}
            chunk = fh.read(KS_PIECE)
            if first:
                if b"\0" in chunk[:4096]:
                    return rel, None, False, {}
                first = False
            if not chunk and not rest:
                break
            data = rest + chunk
            if chunk:
                cut = data.rfind(b"\n") + 1
                if cut == 0:                       # one line longer than a piece: keep reading
                    rest = data
                    continue
                data, rest = data[:cut], data[cut:]
            else:
                rest = b""
            size = len(data)
            if table:
                data = b"\n".join(l for l in data.split(b"\n") if not SUCCESS_ROW.search(l))
            for f, c in counts.items():
                wh = whens[f]
                if isinstance(f, tuple):               # a fragment with a line check: count the lines that pass it
                    frag, lrx = f[0], _line_rx(f[1])
                    pos, seen = data.find(frag), -1
                    while pos >= 0:
                        ls = data.rfind(b"\n", 0, pos) + 1
                        le = data.find(b"\n", pos)
                        le = len(data) if le < 0 else le
                        if ls != seen and lrx.search(data[ls:le]):
                            if c[1] is None and not table:
                                c[1] = lines_before + data.count(b"\n", 0, ls) + 1
                            c[0] += 1
                            wh.add(_line_time(data, ls, ref, table, off), bool(ycut) and bytes_before + ls < ycut)
                        seen = ls
                        pos = data.find(frag, le)
                    continue
                n = data.count(f)
                if n:
                    if c[1] is None and not table:
                        c[1] = lines_before + data.count(b"\n", 0, data.find(f)) + 1
                    c[0] += n
                    pos, seen, w = data.find(f), -1, None
                    longer = [(b, b.find(f)) for b in conts.get(f, [])]
                    while pos >= 0:
                        if not any(pos - o >= 0 and data.startswith(b, pos - o) for b, o in longer):
                            ls = data.rfind(b"\n", 0, pos) + 1
                            if ls != seen:
                                w, seen = _line_time(data, ls, ref, table, off), ls
                            wh.add(w, bool(ycut) and bytes_before + ls < ycut)
                        pos = data.find(f, pos + len(f))
            lines_before += data.count(b"\n")
            bytes_before += size
            if not chunk:
                break
    return rel, counts, False, dict((f, (w.first, w.last, w.days, w.old, w.notime)) for f, w in whens.items())


def scan_known_strings(t, kb, cap=None, budget=30.0, role="satellite", parallel=True, ref=None, off=0):
    """Count each known error string in the files it belongs to: whole files, exact, case-sensitive substring counts.
    Strings about Satellite internals are skipped on other hosts, and in the task tables rows whose result is 'success'
    are left out. Large reports are counted in worker processes, one file per job."""
    import time
    t0 = time.time()
    by_file, cache = {}, {}
    for s in kb["sigs"]:
        if not sig_applies(s, role):
            continue
        for f in sig_files(t, s, cache):
            by_file.setdefault(f, []).append(s)
    # the main logs carry most strings: they are counted first, so a time budget never skips them
    files = sorted(by_file, key=lambda x: (-len(by_file[x]), t.size(x)))
    deadline = t0 + budget
    jobs = [(t.root, f, sorted(set(_sig_key(s) for s in by_file[f]), key=repr), bool(TASK_TABLE_RX.search(f)), deadline, ref, off) for f in files]
    results = {}
    pool = None
    if parallel and len(jobs) > 1 and hasattr(os, "fork") and sum(t.size(f) for f in files) > 64 * 1024 * 1024:
        try:
            import multiprocessing
            pool = multiprocessing.get_context("fork").Pool(min(len(jobs), max(2, min(8, os.cpu_count() or 2))), initializer=_init_build_worker)
            for rel, counts, late, whens in pool.imap_unordered(_count_file, jobs, chunksize=1):
                results[rel] = (counts, late, whens)
        except Exception:
            pass
        finally:
            if pool is not None:
                pool.terminate()
                pool.join()
    for jb in jobs:
        if jb[1] not in results:
            rel, counts, late, whens = _count_file(jb)
            results[rel] = (counts, late, whens)
    hits, scanned, late_files = [], [], []
    for f in files:
        counts, late, whens = results[f]
        if late:
            late_files.append(f)
        if counts is None:
            continue
        scanned.append(f)
        dec = lambda k: (k[0].decode("utf-8", "replace"), k[1]) if isinstance(k, tuple) else k.decode("utf-8", "replace")
        byfrag = dict((dec(k), v) for k, v in counts.items())
        bywhen = dict((dec(k), v) for k, v in whens.items())
        inside = _containers([k for k, v in byfrag.items() if v[0] and not isinstance(k, tuple)])
        for s in by_file[f]:
            if s.get("rx"):
                c, line = byfrag.get((s["f"], s["rx"]), (0, None))
                n = c
            else:
                c, line = byfrag.get(s["f"], (0, None))
                n = c - sum(byfrag.get(x, (0, None))[0] for x in inside.get(s["f"], []))
            if n > 0:
                h = {"i": s["i"], "file": f, "n": n, "line": line}
                wf, wl, days, old, notime = bywhen.get((s["f"], s["rx"]) if s.get("rx") else s["f"], (None, None, {}, 0, 0))
                if wf:
                    h["first"], h["last"] = wf.strftime("%Y-%m-%d %H:%M"), wl.strftime("%Y-%m-%d %H:%M")
                    h["days"] = dict((d.strftime("%Y-%m-%d"), k) for d, k in days.items())
                if old:
                    h["old"] = old
                if notime:
                    h["notime"] = notime
                if TASK_TABLE_RX.search(f):
                    h["at"] = "started_at"     # the times are the rows' started_at, written in UTC and shifted to host time
                hits.append(h)
    stopped = ("stopped after %d s; %d files not counted" % (budget, len(late_files))) if late_files else ""
    per_pb = {}
    for h in hits:
        pb = kb["sigs"][h["i"]]["pb"] or "_none"
        x = per_pb.setdefault(pb, {"n": 0, "sigs": set()})
        x["n"] += h["n"]
        x["sigs"].add(h["i"])
    return {"hits": sorted(hits, key=lambda h: (-h["n"], h["i"])), "per_pb": per_pb, "scanned": scanned, "tailed": [],
            "stopped": stopped, "ms": int((time.time() - t0) * 1000), "cap": None}


def known_first_seen(t, ctx):
    """When each counted string was first seen: the time on the line the count points at (its first line in that file).
    Left out when that line has no time, or sits in the part of a year-less log that is over 12 months old."""
    ref = ref_time(ctx)
    for h in (ctx.get("known") or {}).get("hits", []):
        if not h.get("line") or h.get("first"):
            continue
        full = os.path.join(t.root, h["file"])
        try:
            ycut = file_year_cut(full, ref)
            if ycut and line_index(full)[h["line"] - 1] < ycut:
                continue
            _, rows = read_lines(full, h["line"] - 1, h["line"])
            w = parse_when(rows[0][:100], ref) if rows else None
        except Exception:
            w = None
        if w:
            h["first"] = w.strftime("%Y-%m-%d %H:%M")


def scope_known(ctx, kb):
    """A fact next to a counted string when its recorded cause is about a Satellite or Capsule and this host, by its own
    rhsm.conf, registers to the vendor's hosted service instead."""
    host = ctx.get("rhsm_host") or ""
    if ctx.get("role") != "rhel" or not host.endswith("rhsm.redhat.com"):
        return
    for h in (ctx.get("known") or {}).get("hits", []):
        sg = kb["sigs"][h["i"]]
        if re.search(r"Satellite|Capsule|katello|content view|lifecycle environment|activation key", sg["c"] + " " + sg.get("k", ""), re.I):
            h["scope"] = "this host registers to %s, not to a Satellite or Capsule" % host


def known_string_matcher(kb, role="satellite"):
    """One regex over all usable fragments, for marking report lines; returns fn(line) -> sig index or None."""
    frags = {}
    for s in kb["sigs"]:
        if sig_applies(s, role):
            frags.setdefault(s["f"], []).append(s)
    if not frags:
        return lambda line: None
    for f in frags:                                    # strings with a line check are tried before plain ones
        frags[f].sort(key=lambda s: (not s.get("rx"), s["i"]))
    rx = re.compile("|".join(re.escape(f) for f in sorted(frags, key=len, reverse=True)))

    def match(line):
        m = rx.search(line)
        if not m:
            return None
        for s in frags.get(m.group(0), []):
            if not s.get("rx") or re.search(s["rx"], line):
                return s["i"]
        return None
    return match


