    _TAG = r'((?:[^\s:\[\]]|\((?:[^)]*)\))[^\s:\[]*(?:\[[^\]\d][^\]]*\])?)(?:\[(\d+)\])?:(?: |$)(.*)'
    _s3164 = re.compile(r'^(' + MON + r' [ \d]\d \d\d:\d\d:\d\d(?:\.\d{1,6})?) (\S+) (.*)')
    _siso = re.compile(r'^(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:[.,]\d{1,6})?(?:Z|[+-]\d\d:?\d\d)) (\S+) (.*)')
    _s5424 = re.compile(r'^<(\d{1,3})>1 (\S+) (\S+) (\S+) (\S+) (\S+) (-|\[.*?\]) ?(.*)')
    _pri = re.compile(r'^<(\d{1,3})>(?=[A-Z])')
    _tag = re.compile('^' + _TAG)
    _pulp = re.compile(r'^pulp \[([0-9a-f-]*|None)\]: ([\w.]+):(DEBUG|INFO|WARNING|ERROR|CRITICAL): ?(.*)')
    _nm = re.compile(r'^<(trace|debug|info|warn|error)>\s+\[(\d+\.\d+)\] ?(.*)')
    SYSLOG_SEV = ['emerg', 'alert', 'crit', 'err', 'warning', 'notice', 'info', 'debug']

    def _inner(prog, msg, d):
        """The second layout inside a system-log message, for the programs that write one."""
        p = prog or ''
        if p.startswith('pulpcore') or msg.startswith('pulp ['):
            m = _pulp.match(msg)
            if m:
                d['level'] = m.group(3)
                if m.group(1) and m.group(1) != 'None':
                    d['ids']['request'] = m.group(1)
                return
            m = _guni.match(msg)
            if m:
                d['level'] = m.group(3)
            return
        if p.startswith('dynflow-sidekiq') or p == 'sidekiq':
            s = _sidekiq(msg)
            if s:
                d['level'] = s['level']
                d['ids'].update(s['ids'])
            return
        if p == 'NetworkManager':
            m = _nm.match(msg)
            if m:
                d['level'] = m.group(1)
            return
        if p in ('postgres', 'postgresql'):
            m = re.match(r'^(?:\[\d+(?:-\d+)?\] )?(LOG|ERROR|FATAL|PANIC|WARNING|NOTICE|STATEMENT|DETAIL|HINT|CONTEXT): ', msg)
            if m:
                d['level'] = m.group(1)

    def _syslog_tail(fmt, ts, host, rest, year, tz):
        m = _tag.match(rest)
        if not m:
            return None
        prog, pid, msg = m.group(1), m.group(2), m.group(3)
        if len(prog) > 64:
            return None
        d = F(fmt, ts=ts, year=year, tz=tz, host=host, prog=prog, pid=pid, msg=msg)
        _inner(prog, msg, d)
        return d

    def r_syslog(l):
        m = _s5424.match(l)
        if m:
            pri = int(m.group(1))
            return F('syslog', ts=m.group(2), year=True, tz=True, host=None if m.group(3) == '-' else m.group(3),
                     prog=None if m.group(4) == '-' else m.group(4), level=SYSLOG_SEV[pri & 7] if pri < 192 else None, msg=m.group(8))
        pri = None
        pm = _pri.match(l)
        if pm:
            pri = int(pm.group(1))
            l = l[pm.end():]
        m = _s3164.match(l)
        if m:
            d = _syslog_tail('syslog', m.group(1), m.group(2), m.group(3), False, False)
        else:
            m = _siso.match(l)
            if not m:
                return None
            d = _syslog_tail('syslog', m.group(1), m.group(2), m.group(3), True, True)
        if d and pri is not None and pri < 192 and not d['level']:
            d['level'] = SYSLOG_SEV[pri & 7]
        return d

    _lvm = re.compile(r'^(\d\d:\d\d:\d\d\.\d{6}) ([\w-]+)\[(\d+)\] ([\w/.-]+:\d+) +(.*)')

    def r_misc(l):
        m = _lvm.match(l)
        if m:
            return F('lvm-debug', ts=m.group(1), prog='lvm', pid=m.group(3), msg=m.group(5), nodate=True)

    RECOGNISERS = [r_audit, r_foreman, r_proxy, r_candlepin, r_httpd_error, r_access, r_gunicorn, r_kafo, r_rubylogger, r_rhsm, r_rhsmcertd,
                   r_puppetserver, r_postgres, r_tomcat, r_sidekiq, r_dnf, r_yum, r_pylog, r_sssd, r_anaconda, r_pybasic, r_syslog, r_dmesg, r_misc]

    _cont = re.compile(r'^(?:\s+\S| [0-9a-f]{8} \| | \| |Traceback \(most recent call last\)|Caused by: |\tat |\.\.\. \d+ (?:more|common frames)'
                       r'|[\])}]+,?$|-- |\*{5,}|={5,}|-{5,})')

    def frame(l):
        for fn in RECOGNISERS:
            try:
                d = fn(l)
            except Exception:           # a layout that does not fit is "not recognised", never an error
                d = None
            if d:
                return d
        return None

