    _COMP_RX = [(re.compile(p), k) for p, k in (
        (r'^pulpcore-worker', 'pulpcore-worker'), (r'^dynflow-sidekiq@', 'dynflow-sidekiq'), (r'^systemd-', 'systemd'), (r'^dracut', 'dracut'),
        (r'^postfix/', 'postfix'), (r'^sssd', 'sssd'), (r'^krb5_child', 'krb5_child'), (r'^be(\[|$)', 'sssd_be'),
        (r'^(nss|pam|pac|kcm|ifp|autofs)$', 'sssd'), (r'^insights\b', 'insights-client'), (r'^tuned\b', 'tuned'),
        (r'^(anaconda|packaging|storage|program|blivet|ifcfg|simpleline|org\.fedoraproject\.Anaconda)', 'anaconda'),
        (r'^setroubleshoot', 'setroubleshoot'), (r'^(rhsmd|rhsm-facts-service|rhsmcertd-worker)', 'rhsmcertd'),
        (r'^(rhsm|subscription)', 'subscription-manager'), (r'^puppet-', 'puppet'), (r'^audit', 'auditd'))]

    def component(prog):
        if not prog:
            return None
        if prog in COMPONENTS:
            return COMPONENTS[prog]
        base = prog.rsplit('/', 1)[-1]
        if base in COMPONENTS:
            return COMPONENTS[base]
        for rx, key in _COMP_RX:
            if rx.match(prog):
                return COMPONENTS[key]
        return None

    def clip(v, n=PLAIN_VALUE_MAX):
        v = "".join(ch for ch in v if ch.isprintable())
        return v if len(v) <= n else v[:n - 1] + "…"

    def frame_view(d):
        """What the line's layout says, as (label, value) pairs; a part the line does not carry is left out or named as absent."""
        out = [["written by", component(d.get('prog')) or (clip(d['prog'], 60) if d.get('prog') else "a program the line does not name")]]
        if d.get('host'):
            out.append(["on", clip(d['host'], 70)])
        if d.get('ts'):
            ts = d['ts']
            if d.get('uptime'):
                ts += " seconds after boot"
            elif d.get('epoch'):
                try:
                    ts = time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime(float(ts))) + " UTC"
                except (ValueError, OverflowError, OSError):
                    pass
            elif d.get('nodate'):
                ts += " (no date on the line)"
            elif not d.get('year'):
                ts += " (no year on the line)"
            out.append(["at", ts])
        out.append(["level", str(d['level']) if d.get('level') else (d.get('nolevel') or "this format has no level")])
        for k, v in sorted(d.get('ids', {}).items()):
            out.append([k, clip(v, 40)])
        return out

    # ---------------- the catalog: one entry per kind of line ----------------
    CAT = []
    try:
        for e in json.loads(KB_PLAIN_JSON):
            try:
                e["_rx"] = re.compile(e["m"])
                e["_need"] = [f for _, f, _, _ in _string.Formatter().parse(e["s"]) if f]
                CAT.append(e)
            except (re.error, ValueError, KeyError):
                continue                 # one bad entry never takes the tool down
    except (ValueError, NameError):
        pass

    def _one(line, nl):
        out = []
        for e in CAT:
            aa = e.get("aa")
            if (aa and not any(a in nl for a in aa)) or (not aa and e["a"] not in nl):
                continue
            m = e["_rx"].search(line)
            if not m or any(w not in line for w in e.get("an", ())) or any(w in line for w in e.get("nw", ())):
                continue
            out.append((e, m))
        return out

    def hits(line):
        """Entries that match the line as written, or with its runs of spaces collapsed; the most specific first."""
        c = " ".join(line.split())
        nl = c.lower()
        out = _one(line, nl)
        if c != line:
            have = set(id(e) for e, m in out)
            out += [(e, m) for e, m in _one(c, nl) if id(e) not in have]
        out.sort(key=lambda h: -(len(h[0]["a"]) + len(h[0]["m"])))
        return out

    _SECRET = re.compile(r"(://[^/\s:@]+:)[^@\s/]+@")

    def says(e, m):
        """The sentence as [text, is a value from the line] pieces. A group name ending in a digit is an alias of the name
        without it. When a value the sentence needs is not on the line, the sentence without names is used."""
        vals = {}
        for k, v in m.groupdict().items():
            if v not in (None, ""):
                v = clip(_SECRET.sub(r"\1***@", v))
                vals.setdefault(k, v)
                vals.setdefault(k.rstrip("0123456789"), v)
        if not all(n in vals for n in e["_need"]):
            if e.get("g"):
                return [[e["g"], 0]]
            vals = dict((n, vals.get(n, "(not given)")) for n in e["_need"])
        out = []
        for lit, f, _, _ in _string.Formatter().parse(e["s"]):
            if lit:
                out.append([lit, 0])
            if f:
                out.append([vals[f], 1])
        return out

    # ---------------- standard codes, explained only in their printed form ----------------
