        r"(?i)\b(?:status|response|http)[ _-]?code[\"']?[ :=]{1,3}[\"']?([1-5]\d\d)\b(?![/.])",
        r"(?i)\bHTTPS?(?:/[0-9.]+)?(?: (?:error|status|response|code))?[ :=]{1,2}\(?([1-5]\d\d)\b(?![./\d])",
