def pb_lines(ctx, pid):
    """Known-string lines of a playbook found in this report (0 when none)."""
    return ((ctx.get("known") or {}).get("per_pb") or {}).get(pid, {}).get("n", 0)


def _sec_pb_html(ctx, kb, sid):
    have = set(p["id"] for p in kb["playbooks"])
    pbs = [x for x in SECTION_PB.get(sid, []) if x in have]
    if not pbs:
        return ""
    return "<span class='spb'>%s: %s</span>" % ("playbook" if len(pbs) == 1 else "playbooks", " · ".join(
        "<a href='#learn/pb-%s' class='lk' data-card='pb-%s' title='open the playbook%s'>%s%s</a>"
        % (x, x, (": %s known-string lines of it in this report" % fmt_n(pb_lines(ctx, x))) if pb_lines(ctx, x) else "", esc(PB_SHORT.get(x, x)),
           ("<i>%s</i>" % fmt_n(pb_lines(ctx, x))) if pb_lines(ctx, x) else "") for x in pbs))


