def _summary(md, n=170):
    """First plain sentence of a playbook's 'How it works' (or its first prose line), for its card on the Learn home page."""
    sm = re.search(r"^\*Summary:\s*(.+?)\*\s*$", md, re.M)
    if sm:
        return sm.group(1).strip()[:n]
    m = re.search(r"\*\*How it works\.?\*\*\s*(.*?)(?:\n\s*\n|\n\*\*|$)", md, re.S)
    txt = m.group(1) if m else ""
    if not txt.strip():
        for l in md.split("\n"):
            l = l.strip()
            if l and not l.startswith(("|", "*", "#", "-", "`", ">")) and len(l) > 30:
                txt = l
                break
    if not txt.strip():  # no prose: say what the playbook covers
        heads = [h for h in re.findall(r"^\*\*([^*]+?)\.?\*\*\s*$", md, re.M) if h.lower() not in ("where to look", "gotchas", "live", "commands", "offline", "diagram")]
        rows = [r.split("|")[1].strip() for r in md.split("\n") if r.startswith("|") and not r.startswith("|---") and len(r.split("|")) > 2][1:]
        txt = ("Covers: " + ", ".join(h[0].lower() + h[1:] for h in heads[:5]) + ".") if heads else ("What you see: " + " · ".join(rows[:4])) if rows else ""
    txt = re.sub(r"\s*\[\d+\]", "", txt)
    txt = txt.replace("**", "").replace("`", "")
    txt = re.sub(r"^\s*-\s*", "", txt, flags=re.M)
    txt = " ".join(txt.split())
    if not txt:
        return ""
    cut = None if txt.startswith(("Covers:", "What you see:")) else re.match(r"(.{20,%d}?[.:])(\s|$)" % n, txt)
    txt = cut.group(1) if cut else (txt[:n].rsplit(" ", 1)[0] + " …" if len(txt) > n else txt)
    return txt[:-1] + "." if txt.endswith(":") else txt


